//! Numeric parity for the audit text metrics, against a fixture generated by the source's own
//! Python functions (`fixtures/generate_readability_parity.py`).
//!
//! This is the crate's one defence against "the port looks right": the counts, the sentence
//! split, the syllable heuristic and both readability formulas are compared with the numbers the
//! absorbed service produced, including CPython's half-to-even rounding at two decimals.

use conveyor_analysis::site::seo::content_utils::{
    content_words, phrase_in_tokens, readability_metrics, sentence_count, syllable_count, words,
};
use serde::Deserialize;

const FIXTURE: &str = include_str!("fixtures/readability_parity.json");

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
    phrases: Vec<PhraseCase>,
}

#[derive(Deserialize)]
struct Case {
    text: String,
    words: usize,
    content_words: usize,
    sentences: usize,
    syllables: usize,
    flesch_reading_ease: f64,
    gunning_fog: f64,
}

#[derive(Deserialize)]
struct PhraseCase {
    phrase: String,
    text: String,
    expected: bool,
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE).expect("the fixture parses")
}

#[test]
fn every_token_count_matches_the_source() {
    for case in fixture().cases {
        assert_eq!(
            words(&case.text).len(),
            case.words,
            "word count for {:?}",
            first(&case.text)
        );
        assert_eq!(
            content_words(&case.text).len(),
            case.content_words,
            "content-word count for {:?}",
            first(&case.text)
        );
        assert_eq!(
            sentence_count(&case.text),
            case.sentences,
            "sentence count for {:?}",
            first(&case.text)
        );
        let syllables: usize = words(&case.text)
            .iter()
            .map(|word| syllable_count(word))
            .sum();
        assert_eq!(
            syllables,
            case.syllables,
            "syllable count for {:?}",
            first(&case.text)
        );
    }
}

#[test]
fn every_readability_score_matches_the_source_to_two_decimals() {
    for case in fixture().cases {
        let metrics = readability_metrics(&case.text);
        assert_eq!(
            metrics.flesch_reading_ease,
            case.flesch_reading_ease,
            "Flesch Reading Ease for {:?}",
            first(&case.text)
        );
        assert_eq!(
            metrics.gunning_fog,
            case.gunning_fog,
            "Gunning Fog for {:?}",
            first(&case.text)
        );
    }
}

#[test]
fn word_boundary_matching_matches_the_source() {
    for case in fixture().phrases {
        assert_eq!(
            phrase_in_tokens(&case.phrase, &case.text),
            case.expected,
            "phrase {:?} in {:?}",
            case.phrase,
            case.text
        );
    }
}

fn first(text: &str) -> String {
    text.chars().take(40).collect()
}
